bool resolve_expr_lhs(struct xkb_context *ctx, const ExprDef *expr,
                      const char **elem_rtrn, const char **field_rtrn,
                      ExprDef **index_rtrn) {
    switch (expr->type) {
        case EXPR_IDENT:
            *elem_rtrn = expr->name;
            *field_rtrn = NULL;
            *index_rtrn = NULL;
            return true;

        case EXPR_FIELD: {
            const ExprDef *base_expr = expr->left;
            if (!resolve_expr_lhs(ctx, base_expr, elem_rtrn, field_rtrn, index_rtrn))
                return false;
            *field_rtrn = expr->name;
            return true;
        }

        case EXPR_ARRAY: {
            const ExprDef *base_expr = expr->left;
            if (!resolve_expr_lhs(ctx, base_expr, elem_rtrn, field_rtrn, index_rtrn))
                return false;
            *index_rtrn = expr->right;
            return true;
        }

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                            "Unexpected operator in LHS resolution: %d\n", expr->type);
            return false;
    }
}

